/**
 * SAML Relying Party UPDATE handler (samlgw2)
 *
 * Updates RP config on samlgw2 and SP info in DynamoDB.
 */

import { GetItemCommand, PutItemCommand, QueryCommand } from '@aws-sdk/client-dynamodb';
import { assertHttpsUrls } from 'admin-auth';
import {
  createSamlGw2ClientFromEnv,
  buildSamlgw2ItorgId,
  isEncodableSamlRpName,
} from '../samlgw2-client/index.mjs';
import {
  isPublicHttpsUrl,
  lockedMetadataUrlViolation,
  SP_METADATA_URL_FIELDS,
} from '../samlgw2-client/rp-templates.mjs';

async function getTenantInfo(tenantId, dynamodb, tenantTable) {
  const result = await dynamodb.send(new QueryCommand({
    TableName: tenantTable,
    KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
    ExpressionAttributeValues: {
      ':id': { S: `TENANT#${tenantId}` },
      ':sk_prefix': { S: 'TENANT#' },
    },
  }));
  if (!result.Items || result.Items.length === 0) return null;
  const item = result.Items[0];
  return { orgId: item.org_id?.S };
}

async function getSamlgw2ItorgId(tenantOrgId, dynamodb, tenantTable) {
  try {
    const result = await dynamodb.send(new QueryCommand({
      TableName: tenantTable,
      KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
      ExpressionAttributeValues: {
        ':id': { S: `ORG#${tenantOrgId}` },
        ':sk_prefix': { S: 'ORG#' },
      },
      ProjectionExpression: 'samlgw2_itorg_id',
    }));
    const stored = result.Items?.[0]?.samlgw2_itorg_id?.S;
    if (stored) return stored;
  } catch (e) {
    console.log('Failed to query org:', e.message);
  }
  return buildSamlgw2ItorgId(process.env.ACCOUNT_ID, tenantOrgId);
}

export function isValidSamlRpUpdate(rpName, payload) {
  if (!isEncodableSamlRpName(rpName)
    || !payload
    || typeof payload !== 'object'
    || Array.isArray(payload)) {
    return false;
  }

  return [payload.id, payload.rpName]
    .filter(value => value !== undefined && value !== null)
    .every(value => value === rpName);
}

/**
 * Normalize and validate the saml settings block of an update payload.
 *
 * - null/undefined, or a nameid without either key → undefined
 *   (SAML settings are not part of this update)
 * - nameid with both fields explicitly empty → validation error
 *   (clearing NameID settings is not supported — it would silently
 *   leave the gateway config unchanged while reporting success)
 * - nameid with only one of the two set → validation error (an incomplete
 *   nameid object would wipe the other value on the gateway)
 *
 * @returns {Object|undefined} normalized saml block
 * @throws {Error} with statusCode 400 and expose=true on invalid input
 */
export function normalizeSamlSettings(saml) {
  if (saml === null || saml === undefined) return undefined;

  const invalid = (message) => {
    const error = new Error(message);
    error.statusCode = 400;
    error.expose = true;
    return error;
  };

  if (typeof saml !== 'object' || Array.isArray(saml)) {
    throw invalid('saml must be an object');
  }

  const nameid = saml.nameid;
  if (nameid === null || nameid === undefined) return undefined;
  if (typeof nameid !== 'object' || Array.isArray(nameid)) {
    throw invalid('saml.nameid must be an object');
  }

  // Neither key present at all → SAML settings not part of this update
  if (!('format' in nameid) && !('source_claim' in nameid)) return undefined;

  // Strip ALL whitespace, not just the ends: claim names and format URNs can
  // never contain spaces, and a pasted "custom: immutableId" would otherwise
  // be stored verbatim and never match the Cognito claim.
  const format = typeof nameid.format === 'string' ? nameid.format.replace(/\s+/g, '') : '';
  const sourceClaim = typeof nameid.source_claim === 'string' ? nameid.source_claim.replace(/\s+/g, '') : '';

  if (!format && !sourceClaim) {
    throw invalid('NameID settings cannot be cleared — provide both a NameID format and a source claim');
  }
  if (!format || !sourceClaim) {
    throw invalid('Both NameID format and NameID source claim are required');
  }

  return { ...saml, nameid: { ...nameid, format, source_claim: sourceClaim } };
}

export const putResData = async (
  rpName,
  payload,
  dynamodb,
  tenantId,
  tenantTable,
  spInfoTable,
) => {

  if (!isValidSamlRpUpdate(rpName, payload)) {
    throw new Error('RP name in request body must match the request path');
  }

  // Stored URLs are rendered as links in the Admin Portal (amfa-442 #9).
  // Both the camelCase and snake_case aliases below are read into the record.
  assertHttpsUrls(payload, ['serviceUrl', 'login_url', 'metadataUrl', 'sp_metadata_url', 'logoUrl', 'logo_url']);

  // The shared gateway fetches sp.metadata_url (amfa-442 A3): public host
  // only, and a template that locks it keeps its own value.
  const invalid = (message) => {
    const error = new Error(message);
    error.statusCode = 400;
    error.expose = true;
    error.type = 'validation_error';
    return error;
  };
  for (const field of SP_METADATA_URL_FIELDS) {
    if (payload[field] && !isPublicHttpsUrl(payload[field])) {
      throw invalid(`${field}: must be an https:// URL to a public hostname`);
    }
  }
  // The lock is the STORED template's: a request may not relabel a Microsoft
  // or Dropbox RP as "custom" to replace its metadata URL.
  const stored = await dynamodb.send(new GetItemCommand({
    TableName: spInfoTable,
    Key: { id: { S: `#SAML#${rpName}` } },
    ProjectionExpression: 'template',
  }));
  const storedTemplate = stored.Item?.template?.S || 'custom';
  if (payload.template && payload.template !== storedTemplate) {
    throw invalid(`template: cannot change from ${storedTemplate}`);
  }
  const locked = lockedMetadataUrlViolation(storedTemplate, payload);
  if (locked) throw invalid(locked);

  const tenantInfo = await getTenantInfo(tenantId, dynamodb, tenantTable);
  if (!tenantInfo?.orgId) throw new Error('Tenant has no org');

  const itorgId = await getSamlgw2ItorgId(tenantInfo.orgId, dynamodb, tenantTable);
  const customerName = tenantId.toLowerCase();

  const samlSettings = normalizeSamlSettings(payload.saml);

  // Update RP on samlgw2 if config fields are provided.
  // A gateway failure aborts the whole update (no local write) so the UI
  // never reports success for settings that did not reach the gateway.
  if (payload.claim_mappings || samlSettings || payload.sp_metadata_url || payload.display_name) {
    const rpConfig = {};
    if (payload.display_name) rpConfig.display_name = payload.display_name;
    if (payload.login_url || payload.serviceUrl) rpConfig.login_url = payload.login_url || payload.serviceUrl;
    if (payload.logo_url || payload.logoUrl) rpConfig.logo_url = payload.logo_url || payload.logoUrl;
    if (payload.sp_metadata_url) rpConfig.sp = { metadata_url: payload.sp_metadata_url };
    if (payload.claim_mappings) rpConfig.claim_mappings = payload.claim_mappings;
    if (samlSettings) rpConfig.saml = samlSettings;

    try {
      const samlgw2 = createSamlGw2ClientFromEnv();
      await samlgw2.updateRelyingParty(itorgId, customerName, rpName.toLowerCase(), rpConfig);
      console.log(`RP '${rpName}' updated on samlgw2`);
    } catch (gw2Error) {
      console.error('samlgw2 update RP error:', gw2Error.message);
      const error = new Error(`Failed to update RP on SAML Gateway: ${gw2Error.message}`);
      error.statusCode = 502;
      error.expose = true;
      throw error;
    }
  }

  // Update SP info in DynamoDB
  const samlgw2 = createSamlGw2ClientFromEnv();
  const idpMetadataUrl = samlgw2.getIdpMetadataUrl(itorgId, customerName, rpName.toLowerCase());
  const callbackUrl = samlgw2.getOidcCallbackUrl(itorgId, customerName, rpName.toLowerCase());

  const params = {
    Item: {
      id: { S: `#SAML#${rpName}` },
      name: { S: payload.name || payload.display_name || '' },
      logoUrl: { S: payload.logoUrl || payload.logo_url || '' },
      serviceUrl: { S: payload.serviceUrl || payload.login_url || '' },
      released: { BOOL: payload.released ? true : false },
      groups: { L: (Array.isArray(payload.groups) ? payload.groups : []).filter(g => typeof g === 'string').map(g => ({ S: g })) },
      template: { S: storedTemplate },
      rpName: { S: rpName },
      idpMetadataUrl: { S: idpMetadataUrl },
      callbackUrl: { S: callbackUrl },
      metadataUrl: { S: payload.metadataUrl || payload.sp_metadata_url || '' },
    },
    ReturnConsumedCapacity: 'TOTAL',
    TableName: spInfoTable,
  };

  await dynamodb.send(new PutItemCommand(params));
  console.log('SP info updated in DynamoDB');

  return payload;
};

export default putResData;
